                if (i + 1 < len && line[i + 1] == '"') {
                    currentField += '"';
                    i += 2;
                } else {
                    // End of quoted field
                    inQuotes = false;
                    i++;
                }
            } else {
                currentField += c;
                i++;
            }
        } else {
            if (c == '"') {
                // Start of quoted field
                inQuotes = true;
                fieldStarted = true;
                i++;
