                // End of field
                fields.push_back(currentField);
                currentField.clear();
                fieldStarted = false;
                i++;
            } else {
                currentField += c;
                fieldStarted = true;
                i++;
            }
        }
    }

    // Add the last field
    fields.push_back(currentField);

    return fields;
}

