// Parses a single CSV line according to RFC 4180.
// Handles quoted fields, escaped quotes (""), and commas within quotes.
// Returns a vector of parsed fields.
std::vector<std::string> parseCsvLine(const std::string& line) {
    std::vector<std::string> fields;
    std::string currentField;
    size_t i = 0;
    size_t n = line.size();

    while (i < n) {
        // Check if we're at the start of a quoted field
        if (i < n && line[i] == '"') {
            // Quoted field
            i++; // skip opening quote
            currentField.clear();
            bool inQuotes = true;
            while (i < n) {
                if (line[i] == '"') {
                    // Check for escaped quote (double quote)
                    if (i + 1 < n && line[i + 1] == '"') {
                        currentField += '"';
                        i += 2;
                    } else {
                        // End of quoted field
                        i++; // skip closing quote
                        inQuotes = false;
                        break;
                    }
                } else {
                    currentField += line[i];
                    i++;
                }
            }
            // After closing quote, expect either end of line or a comma
            if (i < n && line[i] != ',') {
                throw std::runtime_error("Expected comma or end of line after quoted field");
            }
            fields.push_back(currentField);
            if (i < n) {
                i++; // skip the comma
            }
        } else {
            // Unquoted field
            currentField.clear();
            while (i < n && line[i] != ',') {
                currentField += line[i];
                i++;
            }
            fields.push_back(currentField);
            if (i < n) {
                i++; // skip the comma
            }
        }
    }

    return fields;
}

