#include <string>
#include <vector>
#include <cassert>
#include <stdexcept>

// Parses a single CSV line according to RFC 4180.
// Handles quoted fields, escaped quotes (""), and commas within quotes.
// Returns a vector of parsed fields.
std::vector<std::string> parseCsvLine(const std::string& line) {
    std::vector<std::string> fields;
    std::string currentField;
    bool inQuotes = false;
    size_t i = 0;
    size_t n = line.size();

    while (i < n) {
        char c = line[i];

        if (inQuotes) {
            if (c == '"') {
                // Check for escaped quote (double quote)
                if (i + 1 < n && line[i + 1] == '"') {
                    currentField += '"';
                    i += 2;
                } else {
                    // End of quoted field
                    inQuotes = false;
                    i++;
                }
            } else {
                currentField += c;
                i++;
            }
        } else {
            if (c == '"') {
                // Start of quoted field
                inQuotes = true;
                i++;
            } else if (c == ',') {
                // End of field
                fields.push_back(currentField);
                currentField.clear();
                i++;
            } else {
                currentField += c;
                i++;
            }
        }
    }

    // Push the last field
    fields.push_back(currentField);

    return fields;
}

