std::vector<std::string> parseCsvLine(const std::string& line) {
    std::vector<std::string> fields;
    std::string currentField;
    bool inQuotes = false;
    bool fieldStarted = false; // Track if we've started reading a field (to handle empty fields)

    for (size_t i = 0; i < line.size(); ++i) {
        char c = line[i];

        if (inQuotes) {
            if (c == '"') {
                // Check if next char is also a quote (escaped quote)
                if (i + 1 < line.size() && line[i + 1] == '"') {
                    currentField += '"';
                    ++i; // Skip the next quote
                } else {
                    inQuotes = false;
                }
            } else {
                currentField += c;
            }
        } else {
            if (c == '"') {
                // Entering quotes. Only valid at the start of a field or after a comma.
                // Per RFC 4180, quotes must be at the beginning of the field.
                if (fieldStarted) {
                    // Quote not at start of field - this is technically malformed, 
                    // but we can handle it by treating it as part of the field
                    // or throw. For robustness, let's treat it as a literal quote.
                    // However, strict RFC 4180 would consider this invalid.
                    // Let's just append it as a literal character for leniency.
                    currentField += c;
                    inQuotes = true;
                } else {
                    inQuotes = true;
                    fieldStarted = true;
                }
            } else if (c == ',') {
                fields.push_back(currentField);
                currentField.clear();
                fieldStarted = false;
            } else {
                currentField += c;
                fieldStarted = true;
            }
        }
    }

    // Push the last field
    fields.push_back(currentField);

    return fields;
}

