std::vector<std::string> parseCsvLine(const std::string& line) {
    std::vector<std::string> fields;
    std::string currentField;
    bool inQuotes = false;
    bool fieldStarted = false; // Track if we've started reading a field (to handle empty fields)

    for (size_t i = 0; i < line.size(); ++i) {
        char c = line[i];

        if (inQuotes) {
            if (c == '"') {
                // Check if next char is also a quote (escaped quote)
                if (i + 1 < line.size() && line[i + 1] == '"') {
                    currentField += '"';
                    ++i; // Skip the next quote
                } else {
                    // End of quoted section
                    inQuotes = false;
                }
            } else {
                currentField += c;
            }
        } else {
            if (c == '"' && !fieldStarted) {
                // Start of a quoted field
                inQuotes = true;
                fieldStarted = true;
            } else if (c == ',') {
                // End of field
                fields.push_back(currentField);
                currentField.clear();
                fieldStarted = false;
            } else {
                currentField += c;
                fieldStarted = true;
            }
        }
    }

    // Add the last field
    fields.push_back(currentField);

    return fields;
