            __nanosleep(100);
#else
            NO_DEVICE_CODE;
#endif // __CUDA_ARCH__ >= GGML_CUDA_CC_VOLTA
        }
    }

    __syncthreads();

    // ACQUIRE: Ensure peer's writes to host_other are visible to this block.
    // This is crucial because the spin-wait only guarantees the flag is set,
    // not that the data preceding it is coherent in the local L1/L2 cache.
    __threadfence_system();

