    std::vector<std::string> fields;
    std::string current;

    enum State { Start, InUnquoted, InQuoted, QuoteInQuoted };
    State state = State::Start;

    for (size_t i = 0; i < line.size(); ++i) {
        char c = line[i];

        switch (state) {
            case State::Start:
                if (c == '"') {
                    state = State::InQuoted;
                } else if (c == ',') {
                    fields.push_back(current);
                    current.clear();
                    // stay in Start
                } else {
                    current += c;
                    state = State::InUnquoted;
                }
                break;

            case State::InUnquoted:
                if (c == ',') {
                    fields.push_back(current);
                    current.clear();
                    state = State::Start;
                } else {
                    current += c;
                }
                break;

            case State::InQuoted:
                if (c == '"') {
                    state = State::QuoteInQuoted;
                } else {
                    current += c;
                }
                break;

            case State::QuoteInQuoted:
                if (c == '"') {
                    current += '"'; // escaped quote
                    state = State::InQuoted;
                } else if (c == ',') {
                    fields.push_back(current);
                    current.clear();
                    state = State::Start;
