#include <cassert>
#include <stdexcept>

/**
 * Parses a CSV line according to RFC 4180.
 * Handles quoted fields, escaped quotes (""), and commas within quotes.
 *
 * @param line The CSV line to parse.
 * @return A vector of parsed fields.
 * @throws std::runtime_error if the input is malformed (e.g., unbalanced quotes).
 */
std::vector<std::string> parseCsvLine(const std::string& line) {
    std::vector<std::string> fields;
    std::string field;
    size_t i = 0;
    size_t n = line.size();

    while (i <= n) {
        if (i == n) {
            // End of line: push the last field
            fields.push_back(field);
            break;
        }

        char c = line[i];

        if (c == '"') {
            // Start of a quoted field
            i++; // skip the opening quote
            bool inQuotes = true;
            while (i < n && inQuotes) {
                if (line[i] == '"') {
                    if (i + 1 < n && line[i + 1] == '"') {
                        // Escaped quote
                        field += '"';
                        i += 2;
                    } else {
                        // End of quoted field
                        inQuotes = false;
                        i++; // skip the closing quote
                    }
                } else {
                    field += line[i];
                    i++;
                }
            }
            // After closing quote, expect comma or end of line
            if (i < n && line[i] != ',') {
                throw std::runtime_error("Malformed CSV: unexpected character after closing quote");
            }
        } else if (c == ',') {
            // Unquoted field ended by comma
            fields.push_back(field);
            field.clear();
            i++;
        } else {
            // Regular character in an unquoted field
            field += c;
            i++;
        }
    }

    return fields;
}

