    // Phase 1: ... (writes to host_mine) ...

    // FIX: Ensure all threads in the block have completed their writes to host_mine
    __syncthreads();

    // FIX: Now fence to make ALL block writes visible system-wide
    __threadfence_system();

    // Phase 2: thread 0 of each block signals...
