/**
 * Parses a CSV line according to RFC 4180 into a vector of fields.
 * Handles quoted fields, escaped quotes (""), and embedded commas/newlines within quotes.
 */
std::vector<std::string> parseCsvLine(const std::string& line) {
    std::vector<std::string> fields;
    std::string currentField;
    size_t i = 0;
    size_t n = line.size();

    while (i < n) {
        // Check if we're at the start of a quoted field
        if (i < n && line[i] == '"') {
            // Quoted field
            i++; // skip opening quote
            currentField.clear();
            while (i < n) {
                if (line[i] == '"') {
                    // Check if next char is also a quote (escaped quote)
                    if (i + 1 < n && line[i + 1] == '"') {
                        currentField += '"';
                        i += 2;
                    } else {
                        // End of quoted field
                        i++; // skip closing quote
                        break;
                    }
                } else {
                    currentField += line[i];
                    i++;
                }
            }
            fields.push_back(currentField);

            // After a quoted field, expect either a comma or end of line
            if (i < n && line[i] == ',') {
                i++; // skip comma
            }
            // If there's anything else, it's malformed; we just continue
        } else {
            // Unquoted field
            currentField.clear();
            while (i < n && line[i] != ',') {
                currentField += line[i];
                i++;
            }
            fields.push_back(currentField);

            if (i < n && line[i] == ',') {
                i++; // skip comma
            }
        }
    }

    return fields;
}

