#include <vector>
#include <string>
#include <cassert>
#include <cctype>

/**
 * Parses a CSV line according to RFC 4180.
 * Handles:
 * - Quoted fields (double quotes)
 * - Escaped quotes within quoted fields ("" represents a literal ")
 * - Commas within quoted fields
 * - Unquoted fields
 * - Empty fields
 * - Leading/trailing whitespace in unquoted fields (preserved as-is per RFC 4180)
 *
 * @param line The CSV line to parse
 * @return A vector of parsed field values
 */
std::vector<std::string> parseCsvLine(const std::string& line) {
    std::vector<std::string> fields;
    std::string currentField;
    bool inQuotes = false;
    bool fieldStarted = false; // Whether we've started reading a field (to handle empty fields)

    size_t i = 0;
    size_t len = line.size();

    while (i < len) {
        char c = line[i];

        if (inQuotes) {
            if (c == '"') {
                // Check if next char is also a quote (escaped quote)
                if (i + 1 < len && line[i + 1] == '"') {
                    currentField += '"';
                    i += 2;
                } else {
                    // End of quoted field
                    inQuotes = false;
                    i++;
                }
            } else {
                currentField += c;
                i++;
            }
        } else {
            if (c == '"') {
                // Start of quoted field
                inQuotes = true;
                fieldStarted = true;
                i++;
            } else if (c == ',') {
                // End of field
                fields.push_back(currentField);
                currentField.clear();
                fieldStarted = false;
                i++;
            } else {
                currentField += c;
                fieldStarted = true;
                i++;
            }
        }
    }

    // Add the last field
    fields.push_back(currentField);

    return fields;
}

